using UnityEngine;
public class VectorProducts:MonoBehaviour{public Transform vectorA,vectorB;public float dotProduct,crossProductMagnitude;public Vector3 crossProductVector;void Update(){if(!vectorA||!vectorB)return;Vector3 a=vectorA.forward;Vector3 b=(vectorB.position-vectorA.position).normalized;dotProduct=Vector3.Dot(a,b);crossProductVector=Vector3.Cross(a,b);crossProductMagnitude=crossProductVector.magnitude;}void OnDrawGizmos(){if(!vectorA||!vectorB)return;Gizmos.color=Color.blue;Gizmos.DrawRay(vectorA.position,vectorA.forward*2f);Gizmos.color=Color.red;Gizmos.DrawRay(vectorA.position,(vectorB.position-vectorA.position).normalized*2f);Gizmos.color=Color.green;Gizmos.DrawRay(vectorA.position,crossProductVector);Gizmos.color=Color.yellow;Gizmos.DrawWireSphere(vectorA.position+crossProductVector,.2f);float alignment=(dotProduct+1f)/2f;Gizmos.color=Color.Lerp(Color.red,Color.green,alignment);Gizmos.DrawWireSphere(vectorA.position,.3f+alignment*.5f);if(dotProduct>.7f){Gizmos.color=Color.cyan;Gizmos.DrawLine(vectorA.position,vectorB.position);}}}
